/*
 * iot_runtime.h — runtime support for programs generated by iotc.
 *
 * The generated code defines evaluate_rules() and the device table; this
 * runtime supplies sensor input and the device actions. On a real board,
 * read_number/read_state would read hardware and turn_on/turn_off would
 * drive GPIO pins; here they use command-line values and print the result.
 */
#ifndef IOT_RUNTIME_H
#define IOT_RUNTIME_H

#include <stdbool.h>

typedef enum {
    STATE_UNKNOWN = 0,
    STATE_ON, STATE_OFF, STATE_OPEN, STATE_CLOSED, STATE_TRUE, STATE_FALSE
} state_t;

/* Sensor input */
double  read_number(const char *sensor);
state_t read_state(const char *sensor);

/* Device actions */
void turn_on(int device);
void turn_off(int device);
void toggle(int device);
void set_level(int device, double level);

/* Provided by the generated program */
void evaluate_rules(void);
extern const char *const iot_device_names[];
extern const int iot_device_count;

#endif
